from collections import Counter

def find_secret_code(n, x, y):
    if y == 0:
        return [i for i in range(1, n+1)]
    if n == 1:
        return ['*' for _ in range(n)]

    for b in range(1, n+1):
        for a in range(1, b+1):
            if b - a == x:
                continue
            for c in range(a, b):
                if x + c > n:
                    break
                diff = Counter(b) - Counter(c)
                if not diff:
                    continue
                if diff[n - 1 - (x) - c]:
                    continue
                if diff[n + c - x] - 1 == 0:
                    continue
                s_diff = Counter(list(range(n+1)))
                for k in diff:
                    s_diff[k - s_diff[n+1-(x)+c]+1] += diff[k]
                    s_diff[1] -= diff[k]
                if len(s_diff) == y:
                    return list(c) + list(b)

    return None

