def find_suitable_pairs(n, m, gardens):
    result = defaultdict(int)
    for idx in range(n):
        for garden_len in range(gardens[idx][0], gardens[idx][1] + 1):
            if garden_len % 2:
                result[garden_len] += 1
            else:
                result[garden_len] += 0
    total_length = 0
    pairs_quality = defaultdict(int)
    cumu_quality = sorted(list(result.values()))
    g_count = len(cumu_quality)
    for quality in cumu_quality:
        if quality == 0:
            continue
        pairs_quality[quality] += 1
        total_length += (g_count - pairs_quality[quality]) * 2 * quality
        if g_count - pairs_quality[quality] == quality:
            total_length -= g_count * quality
        else:
            total_length += 2 * (g_count - pairs_quality[quality])
        g_count -= pairs_quality[quality]
    print(total_length)

