    return int(n**0.5) ** 2 == n

def find_quadratic_subset(n):
    numbers = set(range(1, n + 1))
    permutation = []
    for subset_size in range(1, n + 2):
        factors = {m for m in numbers if factorial(m) and is_perfect_square(n//m)}
        possible_subsets = [list(range(num, n+1)) for num in factors]
        largest_size = max(map(len, possible_subsets))
        permutation_size = min(largest_size, subset_size)
        for size in range(permutation_size, largest_size + 1):
            for valid_subset in permutations(factors, size):
                if len(valid_subset) == subset_size:
                    remaining_numbers = numbers.difference(factors)
                    remaining_subset_size = len(remaining_numbers)
                    if remaining_subset_size == subset_size:
                        high_order = max(valid_subset)
