from itertools import combinations

def is_quadratic_number(number):
    for i in range(1, int(math.sqrt(number))+1):
        if (number // math.factorial(i)) ** 2 * math.factorial(i) == number:
            return True
    return False

def find_quadratic_subset(n):
    numbers = [i for i in range(1, n + 1)]
    max_size = 0
    best_subset = []
    for size in range(1, len(numbers) + 1):
        for subset in combinations(numbers, size):
            if is_quadratic_number(math.prod([math.factorial(i) for i in subset])):
                current_size = size
                if current_size > max_size:
                    max_size = current_size
                    best_subset = subset
    return (max_size, best_subset)

