def is_quadratic(subset, n):
    factors_seen = set()
    product = 1
    for element in subset:
        product *= math.factorial(element)
        prime_factors = {}
        for prime in range(2, int(math.sqrt(product)) + 1):
            count = 0
            while product % prime == 0:
                count += 1
                product //= prime
            if count > 0:
                if prime not in prime_factors:
                    prime_factors[prime] = count
                else:
                    prime_factors[prime] += count
            if is_natural(product):
                if product not in factors_seen:
                    factors_seen.add(product)
                else:
                    return False
    return len(factors_seen) * 2 == len(subset)

def find_quadratic_subset(n):
    subset_size = 0
    potential_subsets = []
    for x in range(1, n + 1):
        subset = set()
        for y in range(x, min(n, x + n // math.gcd(x, n)) + 1):
