    total_combinations = 0

    # Calculate initial combinations for k squares
    for combination_0 in combinations([(i)*2 for i in range(-2*n+1, 2*n+1)], k):
        for combination_1 in combinations([-j-i for j in range(-1, 2)], k):
            for combination_2 in combinations([(1, 0)] + [(1, -2*i-1), (-1, -2*i-1)] for i in range(-1, 2), k-n):
