        for combination in combinations(combination_0 + combination_1 + combination_2 + combinations([(0, 0), (0, n)] + tuples for tuples in ((2*i, 0), (2*(i+1), 4*i), (-2*(i+1), 0), (-2*i, 0))), k):
            new_combinations = prev_combinations

            if at_least_k_squares:
                found_square = False
                for square in [(combination[i]*2, n-i-2), (combination[i]-2, -(n-i-2)), (-(combination[i+1]), -(combination[i+3]-2)), (-(combination[i+2]), -(combination[i+3]+2)) for i in range(k-n-1)]:
