                        found_square = True
                        break
                new_combinations = pow(2, n, 1000000007) - (prev_combinations if found_square else 0)

            total_combinations += new_combinations
            prev_combinations = new_combinations

            # Reset if n^k case is within modulo bounds
            if prev_combinations >= 0:
