def modpow(a, b, m):
    """Fast modular exponentiation."""
    result = 1
    a = a % m
    while b:
        if b & 1:
            result = (result * a) % m
        b = b >> 1
        a = (a * a) % m
    return result

def kth_power(n, k, m):
    return modpow(n * n + n, 2 * k, m)

def num_ways(n, k):
    if n == 0:
        return 1
    else:
        return num_ways(n - 1, k) * kth_power(k, n, 1000000007)

