def fast_pow(x, y):
    res = 1
    curr = x

    while y:
        if y & 1:
            res *= curr
            res %= m
        curr *= curr
        curr %= m
        y >>= 1

    return res

def get_discrete_log(g, h, g_inv, m):
    mgm = (modinv(m, m*2) - modinv(m, 2)) % m
    res = 0

    while (m0 := fast_pow(mgm - res, m)) < mgm:
