import math

def cost_of_number_generator(cost_list, bit_length):
    lower_bound = [0] * bit_length
    upper_bound = [0] * bit_length
    result = [0] * bit_length
    cumulative_cost = [0] * (2**bit_length)

    for i in range(bit_length):
        lower_bound[i] = cost_list[0] % 2
        upper_bound[i] = cost_list[0] % 2
    for cost in cost_list[1:]:
        for i in range(bit_length):
            cumulative_cost[cost // 2 ** (bit_length - i - 1) % 2] = cost
            upper_bound[i] += (cost // 2 ** (bit_length - i - 1)) % 2
        for i in range(bit_length):
            if lower_bound[i] == upper_bound[i]:
                result[i] += lower_bound[i]
            else:
                result[i] += (lower_bound[i] + upper_bound[i]) % 2

    return sum([result[i] * (2 ** i) for i in range(bit_length)])

def find_min_cost_lcs(cost_list, l, r, bit_length):
    cumulative_cost = [0] * (2**bit_length)
    for cost in cost_list:
        next_cumulative_cost = list(cumulative_cost)
        for i in range(bit_length, 0, -1):
            next_cumulative_cost[cost % 2] = cumulative_cost[(cost - (2 ** i) + r) % (2 ** i) + 1]
            next_cumulative_cost[cost % 2] += (cost + r) // (2 ** i)
            cumulative_cost = next_cumulative_cost[:]
            cost += (2 ** (i - 1))

    return cumulative_cost[-1]

