MOD = 10**9 + 7

def factorial(n):
    result = 1
    for i in range(1, n + 1):
        result = (result * i) % MOD
    return result

def inverse_factorial(n):
    return pow(n, MOD - 2, MOD)

def dp(n, k, cache):
    if not n or not k or k > 6 * n:
        return 1
    if k == 1:
        return factorial(2 * n) % MOD
    if (n, k) in cache:
        return cache[(n, k)]

    total = 0
    for left in range(1, 2 * n + 1):
        right = 2 * n - left
        for upper in range(0, left):
            cross = min(right - left + 1, upper, left - upper)
            next_k = k - cross
            total += cross * dp(left, next_k, cache) % MOD
            total %= MOD

    cache[(n, k)] = total
    return total

