    # Iterate over possible x-coordinates for the first tower
    for x in range(-r, r + 1):
        if x == 0:
            continue
        for y in range(-r, r + 1):
            if y == 0:
                continue
            distance = r * r + x * x + y * y
            for dx in range(-r, r + 1):
                for dy in range(-r, r + 1):
                    if dx == 0 or dy == 0:
                        continue
                    if distance > max_sum:
                        max_sum = distance
                        towers = [(x, y), (x + dx, y + dy)]

    print(max_sum)
    for tower in towers:
        print(*tower)

# Example usage
max_distance_sum(1, 4)
